    async def update_card_holder(
        self,
        *,
        business_profile_id: int,
        card_holder_profile_id: int,
        type: UpdateCardHolderSpendLimitsRequestType,
        aggregate_window: UpdateCardHolderSpendLimitsRequestAggregateWindow,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> CardHolderLimits:
        """
        Create or update daily and monthly spend limits for a cardholder.

        Only the `PURCHASE` limit type is supported for cardholder limits.Any
        other value for `type`, including `ATM_WITHDRAWAL`, is rejected with a
        422. When no limits are configured yet, both `daily` and `monthly` must be
        supplied. Once limits exist, either window can be updated on its own.

        Parameters
        ----------
        business_profile_id : int
            The business profile ID.

        card_holder_profile_id : int
            The personal profile ID of the cardholder.

        type : UpdateCardHolderSpendLimitsRequestType
            The category of spending the limit applies to.

        aggregate_window : UpdateCardHolderSpendLimitsRequestAggregateWindow
            The limits to set, per aggregation window. At least one of `daily` or `monthly` must be provided.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        CardHolderLimits
            Updated cardholder spend limits. See [Retrieve cardholder limits](/api-reference/spend-limits/spendlimitscardholderget).

        Examples
        --------
        import asyncio

        from wise_sdk.generated import AsyncWiseClient
        from wise_sdk.generated.environment import WiseClientEnvironment
        from wise_sdk.generated.spend_limits import (
            UpdateCardHolderSpendLimitsRequestAggregateWindow,
            UpdateCardHolderSpendLimitsRequestAggregateWindowDaily,
            UpdateCardHolderSpendLimitsRequestAggregateWindowDailyValue,
            UpdateCardHolderSpendLimitsRequestAggregateWindowMonthly,
            UpdateCardHolderSpendLimitsRequestAggregateWindowMonthlyValue,
        )

        client = AsyncWiseClient(
            external_correlation_id="YOUR_EXTERNAL_CORRELATION_ID",
            client_id="YOUR_CLIENT_ID",
            client_secret="YOUR_CLIENT_SECRET",
            access_token="YOUR_ACCESS_TOKEN",
            environment=WiseClientEnvironment.SANDBOX,
        )


        async def main() -> None:
            await client.spend_limits.update_card_holder(
                business_profile_id=1000000,
                card_holder_profile_id=1000000,
                type="PURCHASE",
                aggregate_window=UpdateCardHolderSpendLimitsRequestAggregateWindow(
                    daily=UpdateCardHolderSpendLimitsRequestAggregateWindowDaily(
                        value=UpdateCardHolderSpendLimitsRequestAggregateWindowDailyValue(
                            amount=1000.0,
                            currency="GBP",
                        ),
                    ),
                    monthly=UpdateCardHolderSpendLimitsRequestAggregateWindowMonthly(
                        value=UpdateCardHolderSpendLimitsRequestAggregateWindowMonthlyValue(
                            amount=3000.0,
                            currency="GBP",
                        ),
                    ),
                ),
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.update_card_holder(
            business_profile_id=business_profile_id,
            card_holder_profile_id=card_holder_profile_id,
            type=type,
            aggregate_window=aggregate_window,
            request_options=request_options,
        )
        return _response.data
